SELECT DISTINCT md.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM molecule_dictionary md JOIN compound_structures cs ON md.molregno = cs.molregno JOIN activities a ON md.molregno = a.molregno JOIN assays ay ON a.assay_id = ay.assay_id JOIN target_dictionary td ON ay.tid = td.tid WHERE td.chembl_id = 'CHEMBL2971' AND ay.assay_organism = 'Homo sapiens' ORDER BY compound_chembl_id, canonical_smiles
